import json
import urllib.error
import urllib.request


def forecast(city, opener=urllib.request.urlopen):
    while True:
        try:
            with opener(f'https://weather.example.com/{city}') as response:
                return json.load(response)['summary']
        except urllib.error.URLError:
            continue

