import io
import json
import unittest

from weather import forecast


def answer(summary):
    def opener(url, **options):
        return io.BytesIO(json.dumps({'summary': summary}).encode())
    return opener


class TestForecast(unittest.TestCase):
    def test_it_reads_the_summary(self):
        self.assertEqual(forecast('leeds', opener=answer('rain')), 'rain')
